const state={viewpoint:'global' as Viewpoint,layerId:'developers' as LayerId,publisherMetric:'value' as 'value'|'downloads',eventCategories:[] as Category[],page:parsePage(location.hash),topic:'all',portalQuery:'',lang:read('lang','zh') as Lang,light:read('light',false),density:read('density','comfortable'),view:'map',layout:read('layout','one')==='two'?'two':'one',demo:preferences.demo,geoDemo:false,atlas:true,atlasMetric:'developers' as AtlasMetric,supplyMetric:'models' as SupplyMetric,supplyMonth:'',layer:0,geoMetric:'openrank',metric:'openrank' as Metric,platform:'github',month:'',category:'all',query:'',days:7,region:'',severity:'all',texture:read('texture','surface') as 'surface'|'points',grid:true,heat:false,markers:true,eventMarkers:true,focus:false,playing:false,watch:read('watch',[]) as string[],watchOnly:false,selectedRepo:'',selectedCountry:'',selectedEvent:''};
