const mn=(m:Metric)=>metricNames[m][state.lang==='zh'?0:1];
const title=(e:Event)=>state.lang==='en'&&e.titleEn?e.titleEn:e.title;
const date=(s:string|null|undefined)=>s?new Date(s).toLocaleString(state.lang==='zh'?'zh-CN':'en-GB',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const monthList=()=>monthsUntil(data.snapshot.repositories.flatMap(r=>r.metrics.openrank.points.map(p=>p.month)).sort().at(-1)!,24);
const regionName=(code:string,fallback:string)=>{if(['TW','TWN','CN-TW'].includes(code))return t('中国台湾','Taiwan, China');const c=data.geography.layers.flatMap(l=>l.countries).find(c=>c.rawCode===code);return c?countryName(c,state.lang):fallback;};
const allEvents=()=>[...data.feed.events,...data.demo.events,...(intelligence?.signals??[]).map(asDemoEvent)];
const portalContext=():PortalContext=>({lang:state.lang,page:state.page,signals:signalsFor(data.feed.events,intelligence,state.demo),preferences,data,watch:state.watch,topic:state.topic,query:state.portalQuery,fixtureAvailable:!!intelligence,evidence,supplyMetric:state.supplyMetric,supplyMonth:state.supplyMonth});
function savePreferences(next:Preferences){preferences=preferencesFrom(next);state.demo=preferences.demo;save('intelligence',preferences);}
function navigate(page:Page){state.page=page;state.focus=false;state.playing=false;clearInterval(playTimer);history.pushState(null,'',`#${page}`);render();window.scrollTo({top:0});document.querySelector<HTMLElement>('#portal-title')?.focus({preventScroll:true});}
function showSignalOnMap(signal:Signal){state.page='overview';state.view='map';state.eventCategories=[];state.viewpoint='custom';state.eventMarkers=true;state.days=0;state.query='';state.category='all';state.region='';state.severity='all';state.focus=false;history.pushState(null,'','#overview');render();window.scrollTo({top:0});const e=allEvents().find(e=>e.id===(signal.eventId??signal.id));if(e)inspect(e);}
function showProject(repository:string){const r=data.snapshot.repositories.find(r=>r.path===repository);if(!r)return;state.platform=r.platform;state.selectedRepo=r.key;navigate('ecosystem');}
const portalActions=():PortalActions=>({navigate,render,modal,savePreferences,map:showSignalOnMap,project:showProject,toast,filter:(topic,query)=>{state.topic=topic;state.portalQuery=query;render();},toggleDemo:checked=>{savePreferences({...preferences,demo:checked});render();}});
const events=()=>filterEvents(allEvents(),state).filter(e=>!state.eventCategories.length||state.eventCategories.includes(e.category));
const layer=()=>data.geography.layers[state.layer];
const globalAtlas=()=>['developers','contribution','influence'].includes(state.layerId)&&!!evidence;
const publisherLayer=()=>state.layerId==='models'||state.layerId==='datasets';
const layerAvailable=()=>['organizations','facilities'].includes(state.layerId)?false:publisherLayer()?!!observation:['developers','contribution','influence'].includes(state.layerId)?!!evidence:true;
const sceneColorMetric=()=>state.layerId==='developers'?'developers':state.layerId==='contribution'||state.layerId==='datasets'?'contributors':state.layerId==='demo'?state.geoMetric:'openrank';
const sceneMetric=()=>globalAtlas()||publisherLayer()?'atlasValue':state.geoMetric;
const geoValue=(c:Country)=>Number((c as any)[sceneMetric()]??0);
const geoCountries=():Country[]=>!layerAvailable()?[]:globalAtlas()?atlasCountries(evidence!,state.atlasMetric):publisherLayer()?publisherCountries(observation!,state.layerId as 'models'|'datasets',state.publisherMetric):state.geoDemo?data.demo.countries:layer().countries;
const currentMetricName=()=>publisherLayer()?t(state.publisherMetric==='value'?'仓库数':'下载量',state.publisherMetric==='value'?'Repositories':'Downloads'):globalAtlas()?atlasNames[state.atlasMetric][state.lang==='zh'?0:1]:state.layerId==='community'?t('归一化社区 OpenRank','Normalized community OpenRank'):mn(state.geoMetric as Metric);
function setLayer(id:LayerId,custom=true){state.layerId=id;state.geoDemo=id==='demo';state.atlas=['developers','contribution','influence'].includes(id);if(state.atlas)state.atlasMetric=id as AtlasMetric;state.geoMetric='openrank';inspected=null;state.selectedCountry='';if(custom)state.viewpoint='custom';}
function applyViewpoint(id:Exclude<Viewpoint,'custom'>){const p=viewpoints[id];setLayer(p.layer,false);state.viewpoint=id;state.layer=Math.min(p.organization,data.geography.layers.length-1);state.eventCategories=[...p.categories];state.category='all';state.query='';state.region='';state.severity='all';state.days=7;state.eventMarkers=true;state.heat=true;state.markers=true;state.focus=false;render();}
const rows=()=>rank(data.snapshot.repositories,state.platform,state.metric,state.month).filter(r=>!state.watchOnly||state.watch.includes(r.key));
const activeRepo=()=>data.snapshot.repositories.find(r=>r.key===state.selectedRepo)??rows()[0]??data.snapshot.repositories[0];
const logo=openDipperLogo('icon');
const btn=(action:string,text:string,active=false,extra='')=>`<button data-action="${action}" ${extra} class="${active?'active':''}">${text}</button>`;
const badge=(e:Event)=>`<span class="badge ${e.provenance}">${e.provenance==='demo'?t('模拟','DEMO'):e.provenance==='manual'?t('人工核验','REVIEWED'):t('自动采集','COLLECTED')}</span>`;
const metricOptions=()=>Object.keys(metricNames).map(m=>`<option value="${m}" ${m===state.metric?'selected':''}>${mn(m as Metric)}</option>`).join('');
function freshness(){if(data.feedError||!data.feed.generatedAt)return `<span class="od-badge critical">${t('快照不可用','FEED UNAVAILABLE')}</span>`;const age=(Date.now()-Date.parse(data.feed.generatedAt))/3600000;return `<span class="od-badge ${age>2?'demo':'automatic'}" title="${t('快照生成时间','Snapshot generated')} ${date(data.feed.generatedAt)}">${age>2?t('快照待更新','SNAPSHOT AGING'):t('缓存快照','CACHED SNAPSHOT')}</span>`;}
function monthly(){return `<section class="monthly panel"><div class="monthly-label"><span class="status-dot"></span><strong>${t('月度观察','MONTHLY LENS')}</strong><small>${t('仓库月度指标','Monthly repository metrics')}</small></div>${btn('play',state.playing?'Ⅱ':'▶',state.playing,`aria-label="${t('播放月度时间轴','Play monthly timeline')}"`)}<input id="month-slider" type="range" min="0" max="23" value="${monthList().indexOf(state.month)}" aria-label="${t('观察月份','Observation month')}"/><select id="month" aria-label="${t('选择月份','Select month')}">${monthList().map(m=>`<option ${m===state.month?'selected':''}>${m}</option>`).join('')}</select></section>`;}
function analytics(){return `<div class="lower-grid"><section class="panel ranking-panel"><div class="panel-head"><h2>${t('项目脉搏','PROJECT PULSE')}</h2>${btn('watch',state.watchOnly?'★':'☆',state.watchOnly,`aria-label="${t('仅看关注','Watchlist only')}"`)}</div><div class="rank-controls"><select id="platform" aria-label="${t('项目平台','Repository platform')}">${['github','gitlab','gitee','atomgit'].map(p=>`<option ${p===state.platform?'selected':''}>${p}</option>`).join('')}</select><select id="metric" aria-label="${t('仓库指标','Repository metric')}">${metricOptions()}</select></div><div class="rank-table">${repoRows()}</div><div class="panel-foot">${t('同平台 · 同月份 · 样本排名','Same platform · same month · sample ranking')}<a href="./analysis.html">${t('深度分析','Analysis')} ↗</a></div></section><section class="panel trend-panel"><div class="panel-head"><h2>${t('趋势透镜','TREND LENS')}</h2><span>12M</span></div>${trend()}</section></div>`;}
